"""Build the review page from measured results and existing local screenshots."""
import pathlib,json,html
root=pathlib.Path(__file__).parent
r=json.loads((root/'results.json').read_text())
s=r['summary'];metrics=r['public_metrics']
def fmt(value,n=2):return 'N/A' if value is None else f'{value:.{n}f}'
rows=[]
for clip in ['wave','hair','curly','chair','glasses','exit']:
 data={m['model']:m for m in metrics if m['clip']==clip}
 rows.append(f"<tr><th>{clip}</th><td>{fmt(data['old']['flicker'],4)}</td><td>{fmt(data['raw']['flicker'],4)}</td><td>{fmt(data['new']['flicker'],4)}</td><td>{fmt(data['new']['alignment_band_px'])}</td></tr>")
wave={m['model']:m for m in metrics if m['clip']=='wave'}
clips=[{'name':c,'contact':f'/tmp/v5-evaluation/{c}/contact.png','edges':f'/tmp/v5-evaluation/{c}/edges-4x.png'} for c in ['wave','hair','curly','chair','glasses','exit']]
checks=r['checks']
perf=[('Masks / s',s['old']['mask_rate'],s['new']['mask_rate']),('Mask latency, ms',s['old']['mask_latency_ms'],s['new']['mask_latency_ms']),('Mask/frame mismatch p90, frames',s['old']['mask_age_p90_frames'],s['new']['mask_age_p90_frames']),('Wave contour band, px',wave['old']['alignment_band_px'],wave['new']['alignment_band_px']),('Wave additional leakage, %',wave['old']['leakage_frame_fraction']*100,wave['new']['leakage_frame_fraction']*100),('Steady Chrome long tasks',s['old']['long_tasks'],s['new']['long_tasks'])]
perf_rows=''.join(f'<tr><th>{name}</th><td>{fmt(a)}</td><td>{fmt(b)}</td></tr>' for name,a,b in perf)
native_rows=''.join(f"<tr><th>{mode.title()}</th><td>{fmt(v['maskRate'],1)}</td><td>{fmt(v['maskLatencyMs'],1)}</td><td>{fmt(v['renderMs'],1)} / {fmt(v['renderP90Ms'],1)}</td><td>{fmt(r.get('native_cpu',{}).get(mode,{}).get('sum'),1)}</td></tr>" for mode,v in r.get('native',{}).items())
doc='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
body{font-family:var(--font-sans,system-ui);font-size:14px;line-height:1.5;color:var(--foreground);margin:0}p{margin:12px 0}strong{font-weight:650}small,.note{color:var(--muted-foreground);font-size:12px}table{border-collapse:collapse;width:100%;font-variant-numeric:tabular-nums;margin:12px 0 18px}th,td{border-bottom:1px solid var(--border);padding:8px 5px;text-align:right}th:first-child{text-align:left}thead th{font-size:12px;color:var(--muted-foreground);font-weight:600}tbody th{font-weight:500}button{border:1px solid var(--border);border-radius:6px;padding:6px 10px;background:transparent;color:inherit;cursor:pointer;font:inherit;font-size:12px}button[aria-pressed=true]{background:var(--primary);color:var(--primary-foreground)}nav{display:flex;flex-wrap:wrap;gap:6px;margin:16px 0 10px}img{max-width:100%;height:auto;display:block;border-radius:6px}details{border-top:1px solid var(--border);margin-top:16px;padding-top:12px}summary{cursor:pointer;font-weight:600;margin-bottom:12px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:12px}.flag{border-left:3px solid var(--warning);padding-left:12px;margin:16px 0}.label{font-weight:650;margin-top:22px}.caption{font-size:12px;color:var(--muted-foreground);margin-top:6px}@media(max-width:500px){body{font-size:12px}th,td{padding:6px 3px}.pair{grid-template-columns:1fr}}
</style><body>
<p><strong>Frame alignment and privacy are fixed; quality/performance gates remain.</strong></p>
<div class="flag">The 0.012 flicker target is unmet. Native rendering also has intervals/tails above 6 ms. These results do not claim a flawless cutout.</div>
<p class="label">Playing public wave clip · 30 fps source</p><table><thead><tr><th>Measured quantity</th><th>Old MediaPipe</th><th>New Vision</th></tr></thead><tbody>__PERF__</tbody></table>
<p class="note">Mask/frame mismatch compares alpha with its displayed capture. The new pipeline deliberately adds a delay line; zero mismatch does not mean zero live-video latency. The contour band includes model disagreement in the old baseline. Leakage is relative to raw Vision, not ground truth.</p>
<p class="label">Public-clip quality · same-frame references</p><table><thead><tr><th>Clip</th><th>Old flicker</th><th>Raw Vision</th><th>New flicker</th><th>New band px</th></tr></thead><tbody>__QUALITY__</tbody></table>
<p class="note">Pooled slow-pair flicker: __OLD_POOL__ old → __NEW_POOL__ new; raw Vision __RAW_POOL__. Hair/glasses/exit have no eligible slow pairs. The old chair cutout drops much of the second person; its lower flicker is not a quality win.</p>
<nav id="clips" aria-label="Public clip"></nav><img id="contact" src="/tmp/v5-evaluation/wave/contact.png" alt="Wave contact sheet: old cutout, raw Vision and new pipeline"><p class="caption">Rows: old engine, raw Vision, new pipeline. Identical source frames. Public footage attribution is retained in the evaluation README and original bakeoff clips.json.</p>
<details><summary>Hair / hand crops at exactly 4×</summary><img id="edges" src="/tmp/v5-evaluation/wave/edges-4x.png" alt="Four-times edge crops"></details>
<details><summary>Zoom 1 and 3</summary><img src="/tmp/v5-evaluation/zoom-contact.png" alt="Public wave at zoom one and three"><div class="pair"><img src="/tmp/v5-evaluation/zoom-1-edge-4x.png" alt="Zoom one hair edge enlarged four times"><img src="/tmp/v5-evaluation/zoom-3-edge-4x.png" alt="Zoom three hair edge enlarged four times"></div><p class="caption">All 254 intermediate 8-bit alpha levels appeared in both zoom captures. This is a continuity check, not proof of correct fine hair.</p></details>
<details><summary>Native bundle · live camera</summary><table><thead><tr><th>Mode</th><th>Masks/s</th><th>Latency ms</th><th>Render p50 / p90 ms</th><th>CPU %*</th></tr></thead><tbody>__NATIVE__</tbody></table><div class="pair"><div><img src="/tmp/v5-shots/native-replace.png" alt="Native window in Replace"><p class="caption">Replace</p></div><div><img src="/tmp/v5-shots/native-blur.png" alt="Native window in Blur"><p class="caption">Blur</p></div></div><p class="caption">The final camera scene was empty; earlier live trials showed a person and faint wall/shadow residue. Current-build live-person acceptance remains a maintainer check. Native screenshots stay under /tmp/v5-shots/. *Eight-second CPU-time deltas for identified desktop and WK processes; 100% means one CPU core. Other system services and accelerator power are outside this scope.</p></details>
<details><summary>Review findings H1–L20</summary>__FINDINGS__</details><p class="note">__RUST__ Rust tests · __NODE__ Node tests in __FILES__ individual files · clean workspace clippy · browser privacy, timeout, fallback, GPU restore, resize/source-change, visibility and coordinate checks passed. RVM/hybrid assets are parked outside ui; 40,008,824 model/runtime bytes leave the app bundle.</p>
<script>const clips=__CLIPS__;const nav=document.getElementById('clips');for(const clip of clips){const b=document.createElement('button');b.textContent=clip.name;b.setAttribute('aria-pressed',String(clip.name==='wave'));b.onclick=()=>{document.getElementById('contact').src=clip.contact;document.getElementById('edges').src=clip.edges;document.getElementById('contact').alt=clip.name+' old, raw Vision and new contact sheet';for(const c of nav.children)c.setAttribute('aria-pressed',String(c===b));};nav.append(b);}console.log('Evidence page initialized',clips.length,'public clips');</script></body></html>'''
for key,value in {'FINDINGS':'<table><tbody>'+''.join('<tr><th>'+html.escape(line.split('|')[1].strip())+'</th><td style="text-align:left">'+html.escape(line.split('|')[2].strip())+'</td></tr>' for line in (root/'README.md').read_text().splitlines() if line.startswith('| H') or line.startswith('| M') or line.startswith('| L'))+'</tbody></table>','PERF':perf_rows,'QUALITY':''.join(rows),'NATIVE':native_rows,'CLIPS':json.dumps(clips),'OLD_POOL':fmt(s['old']['pooled_flicker'],4),'NEW_POOL':fmt(s['new']['pooled_flicker'],4),'RAW_POOL':fmt(s['raw']['pooled_flicker'],4),'RUST':str(checks['rust_passed']),'NODE':str(checks['node_passed']),'FILES':str(checks['node_files'])}.items():doc=doc.replace('__'+key+'__',value)
(root/'evidence.html').write_text(doc)
print('Evidence page ready')
